/* 2. explode ITEMS for purchase events */
purchase_items AS (
    SELECT
        TO_DATE("EVENT_DATE",'YYYYMMDD')                      AS purchase_date,
        DATE_TRUNC('month', TO_DATE("EVENT_DATE",'YYYYMMDD')) AS purchase_month,
        "USER_PSEUDO_ID"                                     AS user_id,
        itm.value:"item_name"::string                        AS item_name,
        COALESCE(itm.value:"quantity"::number , 1)           AS quantity
    FROM   all_events
           ,LATERAL FLATTEN(input => "ITEMS") itm
    WHERE  "EVENT_NAME" = 'purchase'
),

/* 3. customers who bought the Google Red Speckled Tee in each month */
tee_buyers AS (
    SELECT DISTINCT user_id, purchase_month
    FROM   purchase_items
    WHERE  item_name = 'Google Red Speckled Tee'
)

/* 4. aggregate “other” products for those customers and select the top one per month */
SELECT  pi.purchase_month                                         AS month_start,
        pi.item_name                                              AS most_purchased_other_product,
        SUM(pi.quantity)                                          AS total_quantity
FROM    purchase_items pi
JOIN    tee_buyers     tb
       ON  pi.user_id        = tb.user_id
       AND pi.purchase_month = tb.purchase_month
WHERE   pi.item_name <> 'Google Red Speckled Tee'
GROUP BY pi.purchase_month, pi.item_name
QUALIFY  ROW_NUMBER() OVER (PARTITION BY pi.purchase_month
                            ORDER BY SUM(pi.quantity) DESC) = 1
ORDER BY month_start;